mapper.select:
SELECT stat_date, MAX(updated_at) AS updated_at
FROM hot_search_daily_group WHERE stat_date < #{before}
GROUP BY stat_date ORDER BY stat_date DESC LIMIT #{limit}

SELECT group_id, group_name, vector_version, search_count, user_count, score, rank_no, updated_at
FROM hot_search_daily_group
WHERE stat_date = #{date} AND user_count >= #{minUsers}
AND rank_no > #{after}
ORDER BY rank_no LIMIT #{limit}

SELECT MIN(id) AS keyword_id, raw_keyword, COUNT(*) AS search_count, COUNT(DISTINCT user_id) AS user_count
FROM hot_search_event WHERE stat_date = #{date} AND group_id = #{groupId}
GROUP BY raw_keyword

HAVING MIN(id) > #{after}
ORDER BY keyword_id LIMIT #{limit}

SELECT user_id, COUNT(*) AS search_count, MIN(happened_at) AS first_happened_at, MAX(happened_at) AS last_happened_at
FROM hot_search_event
WHERE stat_date = #{date} AND group_id = #{groupId} AND raw_keyword = #{rawKeyword}
AND user_id > #{after}
GROUP BY user_id ORDER BY user_id LIMIT #{limit}

SELECT id, event_id, stat_date, happened_at, event_hour, user_id, raw_keyword,
       grouping_keyword, group_id, group_name, vector_version
FROM hot_search_event
WHERE stat_date = #{date} AND group_id = #{groupId} AND raw_keyword = #{rawKeyword}
AND user_id = #{userId}

    AND (happened_at > #{afterAt} OR (happened_at = #{afterAt} AND id > #{afterId}))

ORDER BY happened_at, id LIMIT #{limit}
